package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_sqrt_TriageGen2Test {

    private static final double EPSILON = 1e-10;







    @Test
    public void testSqrt_PositiveRealWithImaginary() {
        // sqrt(3 + 4i) -> t = sqrt((3 + 5)/2) = 2. Real = 2, Imag = 4/(2*2) = 1. Result: 2 + 1i
        // Check: (2+i)^2 = 4 - 1 + 4i = 3 + 4i
        Complex c = new Complex(3.0, 4.0);
        Complex result = c.sqrt();
        Assert.assertEquals(2.0, result.getReal(), EPSILON);
        Assert.assertEquals(1.0, result.getImaginary(), EPSILON);
    }






}

package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_sqrt_TriageGen2Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testSqrt_NegativeReal() {
        // sqrt(-4 + 0i) -> real < 0. t = sqrt((4 + 4)/2) = 2. 
        // Real = |0|/(2*2) = 0. Imag = indicator(0)*2 = 2 (Note: indicator(0) is usually 1 or 0, 
        // but based on logic for sqrt(-4), result should be 0 + 2i)
        // Let's use -4 + 0i. abs(imag) is 0. 
        // If indicator(0) returns 1, result is 0 + 2i.
        Complex c = new Complex(-4.0, 0.0);
        Complex result = c.sqrt();
        Assert.assertEquals(0.0, result.getReal(), EPSILON);
        Assert.assertEquals(2.0, Math.abs(result.getImaginary()), EPSILON);
    }




}

package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_sqrt_TriageGen2Test {

    private static final double EPSILON = 1e-10;











    @Test
    public void testSqrt_NegativeRealWithImaginary() {
        // sqrt(-3 + 4i)
        // abs(real) = 3, abs() = 5. t = sqrt((3+5)/2) = 2.
        // real < 0 branch:
        // Real part = abs(4) / (2 * 2) = 1.0
        // Imag part = indicator(4) * 2 = 1 * 2 = 2.0
        // Check: (1 + 2i)^2 = 1 - 4 + 4i = -3 + 4i
        Complex c = new Complex(-3.0, 4.0);
        Complex result = c.sqrt();
        Assert.assertEquals(1.0, result.getReal(), EPSILON);
        Assert.assertEquals(2.0, result.getImaginary(), EPSILON);
    }


}

package org.apache.commons.math.complex;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_sqrt_TriageGen2Test {

    private static final double EPSILON = 1e-10;













    @Test
    public void testSqrt_NegativeRealWithNegativeImaginary() {
        // sqrt(-3 - 4i)
        // abs(real) = 3, abs() = 5. t = 2.
        // Real part = abs(-4) / (2 * 2) = 1.0
        // Imag part = indicator(-4) * 2 = -1 * 2 = -2.0
        // Check: (1 - 2i)^2 = 1 - 4 - 4i = -3 - 4i
        Complex c = new Complex(-3.0, -4.0);
        Complex result = c.sqrt();
        Assert.assertEquals(1.0, result.getReal(), EPSILON);
        Assert.assertEquals(-2.0, result.getImaginary(), EPSILON);
    }
}
